/// <summary>
/// PaffH 14.11.24
/// </summary>
/// <param name="_sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(AVAKBVBuildingProjectTable, NDXSyncBVInfoFromRicoKalkButton), FormControlEventType::Clicked)
        ,SuppressBPWarning('BPParameterNotUsed', 'The parameter ist not required in this context')]
public static void NDXSyncBVInfoFromRicoKalkButton_OnClicked(FormControl _sender, FormControlEventArgs e)
{
    FormRun formRunLocal = _sender.formRun();
    if (formRunLocal is NDXKBVBuildingProjectTableFormRicoKalkI)
    {
        NDXKBVBuildingProjectTableFormRicoKalkI nDXKBVBuildingProjectTableFormRicoKalkI = formRunLocal as NDXKBVBuildingProjectTableFormRicoKalkI;
        NDXKBVBuildingProject2RicoKalk nDXKBVBuildingProject2RicoKalk = nDXKBVBuildingProjectTableFormRicoKalkI.parmNDXKBVBuildingProject2RicoKalk();
        FormDataSource KCS_KBVBuildingProjectTable_DS = formRunLocal.dataHelper().FindDataSource(formDataSourceStr(AVAKBVBuildingProjectTable, KCS_KBVBuildingProjectTable));
        KCS_KBVBuildingProjectTable kCS_KBVBuildingProjectTable = KCS_KBVBuildingProjectTable_DS.cursor();

        NDXRicoKalk2KBVBuildingProjectContract contract = NDXRicoKalk2KBVBuildingProjectContract::construct();
        contract.parmKBVBuildingProjectID(kCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
        nDXKBVBuildingProject2RicoKalk.transRicoKalkAng2KBV(contract);
    }
}
